// Mutation harness: the model's tests must PASS the real slugify and FAIL
// each deliberately-broken mutant of slug.js.
const { execFileSync } = require("node:child_process");
const fs = require("node:fs");

const IMPL = "slug.js";
const MUTANTS = [
  // no lowercasing
  ["    .toLowerCase()\n", ""],
  // no run-collapsing: every separator char becomes its own hyphen
  ['    .replace(/[^a-z0-9]+/g, "-")', '    .replace(/[^a-z0-9]/g, "-")'],
  // edge hyphens never stripped
  ['    .replace(/^-+|-+$/g, "");', "    ;"],
];

function runTests() {
  try {
    execFileSync(process.execPath, ["--test", "test_slugify.js"], { stdio: "inherit" });
    return 0;
  } catch {
    return 1;
  }
}

const src = fs.readFileSync(IMPL, "utf8");
for (const [old] of MUTANTS) {
  const count = src.split(old).length - 1;
  if (count !== 1) {
    console.error(`protected implementation file ${IMPL} was modified - the task ` +
      `said not to change it (anchor not found exactly once: ${JSON.stringify(old)})`);
    process.exit(1);
  }
}

if (runTests() !== 0) {
  console.error("model tests FAILED against the correct implementation");
  process.exit(1);
}

let failed = false;
try {
  for (let i = 0; i < MUTANTS.length; i++) {
    const [old, repl] = MUTANTS[i];
    fs.writeFileSync(IMPL, src.replace(old, repl));
    if (runTests() === 0) {
      console.error(`mutation ${i + 1} SURVIVED: the tests still pass against a ` +
        `deliberately broken implementation, so they do not verify the required behavior`);
      failed = true;
      break;
    }
  }
} finally {
  fs.writeFileSync(IMPL, src);
}

if (failed) process.exit(1);
console.log(`PASS (killed all ${MUTANTS.length} mutants)`);

reference_solution.test_slugify.js:
const test = require("node:test");
const assert = require("node:assert");
const { slugify } = require("./slug");

test("lowercases and hyphenates", () => {
  assert.strictEqual(slugify("Hello, World!"), "hello-world");
});

test("collapses runs of separators into one hyphen", () => {
  assert.strictEqual(slugify("spaced   out -- title"), "spaced-out-title");
});

test("strips leading and trailing separators", () => {
  assert.strictEqual(slugify("  !!Big News!!  "), "big-news");
});

test("already clean slugs are unchanged", () => {
  assert.strictEqual(slugify("already-slugged-123"), "already-slugged-123");
});

test("all-separator input becomes empty", () => {
  assert.strictEqual(slugify("!!!"), "");
});

