const test = require("node:test");
const assert = require("node:assert");
const { slugify } = require("./slug");

test("returns a string", () => {
  assert.strictEqual(typeof slugify("Hello"), "string");
});

test("no spaces in output", () => {
  assert.ok(!slugify("two words").includes(" "));
});

test("keeps digits", () => {
  assert.ok(slugify("page 2").includes("2"));
});

test("nonempty input gives nonempty slug", () => {
  assert.ok(slugify("hello").length > 0);
});
